106	     * Normalize an address string to its canonical form: trimmed, whitespace
107	     * collapsed, upper-cased, with common street-type abbreviations expanded.
108	     * Returns {@code null} for a {@code null} input; a value that is blank once
109	     * trimmed normalizes to the empty string.
110	     */
111	    public static String normalizeAddress(String address) {
112	        if (address == null) {
113	            return null;
114	        }
115	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
116	        if (collapsed.isEmpty()) {
117	            return "";
118	        }
119	        String[] tokens = collapsed.split(" ");
120	        StringBuilder sb = new StringBuilder();
121	        for (int i = 0; i < tokens.length; i++) {
122	            if (i > 0) {
123	                sb.append(' ');
124	            }
