401	    private String normalizeTelephone(String telephone) {
402	        if (telephone == null) {
403	            return null;
404	        }
405	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
406	        String digits;
407	        if (cleaned.startsWith("+")) {
408	            digits = cleaned.substring(1);
409	        } else {
410	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
411	            digits = "61" + national;
412	        }
413	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
414	    }
